-- Drafts, unapproved. approved_at is null on purpose: the CRM locks the
-- send button until a human approves the exact wording, and editing the
-- text lapses the approval again.
insert into public.sales_email_drafts (lead_id, subject, body)
select id, 'Arnold Dental Care — one small thing', 'Hi,

I''m Alex — I run n.abl, a small technology business in Nottingham.

Your site calls you "Arnold Dental & Implant Centre", so this may or may not land.

Most businesses doing that have two or three jobs that eat a morning a week and nobody has ever had time to fix.

We take one job that is costing a business time or accuracy and build the right fix for it. Sometimes that is an automation, sometimes a small piece of software, sometimes it is setting up something you already pay for properly.

If it is worth twenty minutes, reply and I''ll suggest a time. If not, no reply needed — I won''t chase you.

Alex
n.abl · nabl.agency

You can stop us contacting you at any time by replying or emailing hello@nabl.agency. We hold only what your company publishes on the Companies House register, the ICO register or your own website — nabl.agency/privacy.' from public.sales_leads where company = 'ARNOLD DENTAL CARE LIMITED'
union all
